from qb import q, write

GM = ["mobile-app-developer", "full-stack-developer", "python-developer", "backend-developer"]
ITEMS = [
    q("csharp", "easy", ["csharp"], "What is the difference between a class and a struct in C#, and why do games care about it?", "A class is a reference type allocated on the heap and a struct is a value type copied on assignment. Games care because many small heap objects create garbage that can cause frame stutters, so small data such as vectors are often structs.", ["Reference vs value type", "Heap allocation and garbage", "Small data as structs"], ["Why can copying a large struct be slow?"]),
    q("csharp", "medium", ["memory"], "What causes garbage collection spikes in a Unity game and how do you reduce them?", "Allocating objects every frame, such as creating new lists, strings or closures in Update, fills the heap and triggers the collector, which pauses the game. Reuse objects with pooling, cache references and avoid string concatenation in hot paths.", ["Per-frame allocations", "Object pooling", "Cache and reuse"], ["How would you find where allocations come from?"]),
    q("csharp", "medium", ["oop"], "How do inheritance and composition differ when building game characters, and which is usually better in Unity?", "Inheritance builds a deep class tree such as Enemy and FlyingEnemy, which becomes rigid. Composition attaches small components such as Health and Movement to an object, which is the Unity model and easier to mix and reuse.", ["Rigid hierarchies", "Components are reusable", "Unity favours composition"], ["How do components talk to each other?"]),
    q("unity", "easy", ["lifecycle"], "What are Awake, Start, Update, FixedUpdate and LateUpdate in Unity and what goes in each?", "Awake and Start initialise an object, Update runs every frame for input and logic, FixedUpdate runs at a fixed rate for physics and LateUpdate runs after all updates, for example for a camera following a target.", ["Initialisation vs per-frame", "FixedUpdate for physics", "LateUpdate for cameras"], ["Why is movement multiplied by Time.deltaTime?"]),
    q("unity", "medium", ["physics"], "Why should physics movement be done in FixedUpdate and what is the difference between a collider and a trigger?", "Physics runs on a fixed time step, so applying forces in FixedUpdate keeps behaviour consistent regardless of frame rate. A collider physically blocks other bodies, while a trigger only reports overlap without blocking.", ["Fixed time step", "Frame-rate independence", "Collider vs trigger"], ["What is a Rigidbody for?"]),
    q("unity", "medium", ["performance"], "A mobile game drops to 20 frames per second. How do you find and fix the cause?", "Use the profiler to see whether the CPU, GPU or memory is the limit, then reduce draw calls with batching and atlases, cut expensive per-frame code, lower overdraw and shader cost, and test on a real low-end device.", ["Profile first", "Draw calls and overdraw", "Test on real devices"], ["What is batching?"]),
    q("unity", "hard", ["architecture"], "How would you structure a Unity project so that game logic is testable and not tied to scenes and components?", "Keep core rules in plain C# classes without Unity dependencies, use MonoBehaviours as thin adapters, communicate with events or interfaces and use scriptable objects for data. Plain classes can then be unit tested.", ["Plain C# for logic", "Thin MonoBehaviours", "Events and data assets"], ["What are the downsides of singletons in games?"]),
    q("unity", "medium", ["pooling"], "What is object pooling and when would you use it for bullets or enemies?", "A pool pre-creates objects and reuses them by activating and deactivating instead of creating and destroying them. This avoids allocation and garbage collection costs for things spawned often, such as bullets.", ["Reuse instead of destroy", "Avoids garbage", "Reset state on reuse"], ["What bug appears if you forget to reset a pooled object?"]),
    q("game-dev", "easy", ["game-loop"], "What is the game loop and why is frame-rate independence important?", "The game loop repeatedly reads input, updates the game state and renders a frame. Movement and timers must use elapsed time, not frame counts, so the game runs at the same speed on fast and slow devices.", ["Input, update, render", "Use elapsed time", "Same speed everywhere"], ["What is a fixed time step?"]),
    q("game-dev", "medium", ["math"], "How would you move an enemy toward the player at a constant speed and make it face the player?", "Compute the direction as the normalised vector from the enemy to the player, multiply it by speed and delta time and add it to the position, and rotate the enemy to look along that direction. Stop when it is close enough.", ["Normalised direction vector", "Speed times delta time", "Rotate toward the direction"], ["Why is normalising needed?"]),
    q("game-dev", "hard", ["ai"], "How would you implement simple enemy behaviour that patrols, chases and attacks?", "Use a finite state machine with states such as patrol, chase and attack and clear transitions based on distance or sight, keeping each state's logic separate. Use pathfinding such as A-star on a navigation mesh for movement.", ["State machine", "Transitions on conditions", "Pathfinding for movement"], ["When would you use a behaviour tree?"]),
    q("game-dev", "medium", ["data-structures"], "Which data structures would you use for an inventory system and for finding all enemies near the player?", "A dictionary from item id to quantity gives fast stack updates for an inventory. For nearby enemies, a spatial structure such as a grid or quadtree avoids checking every enemy each frame.", ["Dictionary for inventory", "Spatial partitioning", "Avoid checking everything"], ["How does a grid speed up collision checks?"]),
    q("mobile", "medium", ["monetisation"], "What do you need to consider when adding ads and in-app purchases to a mobile game?", "Respect the platform's store rules and privacy requirements, avoid interrupting gameplay badly, validate purchases on a server to stop fraud, handle failures and restores and test with sandbox accounts. Keep the experience fair.", ["Store rules and privacy", "Server-side validation", "Sandbox testing"], ["How do you restore a purchase on a new device?"]),
    q("mobile", "medium", ["platforms"], "How do you handle different screen sizes and low-end devices in a mobile game?", "Use anchors and scalable UI, test several aspect ratios, provide quality settings, compress textures and keep builds small. Always test on real low-end hardware, not only the editor.", ["Scalable UI", "Quality settings", "Test on real devices"], ["How do you reduce the build size?"]),
    q("mobile", "hard", ["networking"], "How would you design a basic online leaderboard and prevent obvious cheating?", "Send scores to a server that validates them, for example against plausible ranges or replay data, authenticate players, store scores in a sorted structure or database index and rate limit submissions. Never trust the client alone.", ["Server validates scores", "Authentication and rate limits", "Efficient ranking"], ["How do you handle ties?"]),
    q("backend", "medium", ["api"], "How would you save and load player progress both locally and in the cloud?", "Serialise the data to JSON or a binary format with a version number, save locally for offline play, sync to a server with timestamps and a conflict rule and handle corrupted saves with backups.", ["Versioned save format", "Local plus cloud sync", "Conflict rule and backups"], ["What if the player plays on two devices?"]),
    q("sql", "easy", ["sql"], "Write the idea of a query that returns the top 10 players by score with their rank.", "Select players ordered by score descending with a limit of 10, and add RANK() or ROW_NUMBER() over the same ordering to produce the rank, deciding how ties are shown.", ["ORDER BY score DESC", "LIMIT 10", "RANK window function"], ["How would you get a single player's rank?"]),
    q("dsa", "medium", ["pathfinding"], "Explain breadth-first search and A-star and when you would use each on a game grid.", "Breadth-first search explores outward equally and finds the shortest path on an unweighted grid. A-star adds a heuristic estimate of the distance to the goal, so it finds good paths faster, especially on large maps with different costs.", ["BFS for unweighted grids", "A-star uses a heuristic", "Faster on large maps"], ["What makes a heuristic admissible?"]),
    q("dsa", "hard", ["algorithms"], "How would you find the closest pair among 10,000 points more efficiently than checking all pairs?", "Checking all pairs is O(n squared). Sort or grid the points and compare only neighbours in the same or adjacent cells, or use the divide-and-conquer closest pair algorithm in O(n log n).", ["Brute force is quadratic", "Spatial grid", "Divide and conquer"], ["How does a grid cell size affect speed?"]),
    q("git", "medium", ["version-control"], "Why are game projects hard to manage in Git and how do you deal with large binary assets and scene conflicts?", "Large binaries bloat repositories and scenes or prefabs are hard to merge. Use Git LFS or a suitable version control system, text-based serialisation for scenes, small prefabs and clear ownership so two people do not edit the same scene.", ["Large binary files", "Git LFS", "Avoid editing the same scene"], ["How do you structure scenes to reduce conflicts?"]),
    q("mind-scenario", "medium", ["debugging"], "Scenario: players report the game crashes on some Android phones but not on yours. How do you investigate?", "Collect crash logs from a reporting tool, find the common device, OS version or graphics driver, reproduce on a similar device or emulator, fix the cause, such as memory or an unsupported shader, and release a test build to those users.", ["Crash reporting data", "Find the common factor", "Reproduce and verify"], ["How would you catch this before release?"], kind="scenario"),
    q("mind-scenario", "hard", ["design"], "Scenario: design the system for a daily reward that cannot be claimed twice or by changing the phone's clock.", "Keep the claim time and streak on the server using server time, make the claim request idempotent per day and return the next available time. Never trust the device clock.", ["Server time", "Idempotent claims", "Do not trust the client clock"], ["How would you handle time zones?"], kind="scenario"),
    q("mind-scenario", "easy", ["teamwork"], "Scenario: an artist and a designer disagree with you about how a feature should work. What do you do?", "Listen to their goals, show the options with a quick prototype and the technical cost of each, and decide together or escalate to the lead using the player experience as the common ground.", ["Understand their goals", "Prototype and show costs", "Decide by player experience"], ["How do you give feedback on a game build?"], kind="scenario"),
    q("csharp", "easy", ["collections"], "When would you use a List, a Dictionary and a Queue in game code?", "A List holds ordered items such as the enemies in a wave, a Dictionary gives fast lookup by key such as an item by id, and a Queue processes things in order, such as events or spawn requests. Choose by the operation you do most.", ["List, Dictionary, Queue roles", "Choose by operation", "Lookup cost"], ["What happens when you remove items from a list while looping over it?"]),
    q("project", "easy", ["projects"], "Describe a game or interactive app you built. What was your role, what was the hardest technical problem and how did you test it on devices?", "A strong answer states the game and platform, your own role, one real problem such as performance or physics with its fix and how it was tested on real devices.", ["Own role", "A real problem and fix", "Device testing"], ["What would you improve?"], kind="scenario", roles=GM),
]


def build():
    return write("mindstorm-studios", GM, ITEMS)


if __name__ == "__main__":
    build()
